@router.post("/features/{flag_key}/targets")
async def add_user_to_flag_targets(
    flag_key: str,
    payload: TargetOverridePayload,
    current_user: User = Depends(get_current_user),
    db: AsyncSession = Depends(get_db)
):
    admin_check = await db.scalar(
        select(WorkspaceMember).where(
            WorkspaceMember.workspace_id == payload.target_workspace_id,
            WorkspaceMember.user_id == current_user.id,
            WorkspaceMember.role.in_(["OWNER", "ADMIN"])
        )
    )
    if not admin_check and not current_user.is_superuser:
        raise HTTPException(status_code=403, detail="Forbidden: workspace admin authorization required")

    rule_update = {
        "workspace_id": payload.target_workspace_id,
        "user_key": payload.user_key,
        "variation": payload.desired_variation
    }
    await flag_service_client.add_user_targeting_rule(
        flag_key=flag_key,
        workspace_id=payload.target_workspace_id,
        user_key=payload.user_key,
        variation=payload.desired_variation
    )
    return {"status": "targeting_rule_added", "flag": flag_key, "rule": rule_update}
